#include <iostream>
#include <string>
#include <unistd.h>

// Writes straight to fd 1 with one system call, past std::cout's buffer.
void rawLog(const std::string& text) {
    write(1, text.data(), text.size());
}

int main() {
    std::cout << "1 header\n";
    rawLog("2 raw log\n");                  // overtakes line 1 when fd 1 is a pipe
    std::cout << "3 body\n" << std::flush;  // sends lines 1 and 3 together
    std::cout << "4 header\n" << std::flush;
    rawLog("5 raw log\n");                  // in order: the buffer was empty
    std::cout << "6 body" << std::endl;     // endl is '\n' plus a flush
    return 0;
}

