#include <csignal>
#include <iostream>

volatile std::sig_atomic_t stopRequested = 0;

void onSignal(int) {
    stopRequested = 1;  // only set a flag: no printing inside a handler
}

int main() {
    std::signal(SIGINT, onSignal);
    int recorded = 0;
    for (int tick = 1; tick <= 10 && !stopRequested; ++tick) {
        std::cout << "tick " << tick << '\n';
        ++recorded;
        if (tick == 3) {
            std::raise(SIGINT);  // stands in for Ctrl-C, which nobody can press in the sandbox
        }
    }
    std::cout << "stopped after " << recorded << " ticks, file saved\n";
    return 0;
}

